import re
seq = open('region.fasta').read().split('\n',1)[1].replace('\n','')

# restriction sites / palindromic 4-cuts and 6-cuts (typical type-II sites)
sites4 = {
    'AluI':'AGCT','HaeIII':'GGCC','RsaI':'GTAC','TaqI':'TCGA','MseI':'TTAA',
    'Sau3A':'GATC','HhaI':'GCGC','MspI':'CCGG','BfaI':'CTAG','CviQI':'GTAC',
}
found4 = {k:[m.start()+1 for m in re.finditer(v, seq)] for k,v in sites4.items() if len(re.findall(v,seq))>0}
print("4-cutter hits (1-based):")
for k,v in found4.items():
    print(f"  {k} ({list(sites4.values())[list(sites4.values()).index(next(x for x in sites4.values() if x==v))]}):", len(v), "sites; first at", v[:5])

sites6 = {
    'EcoRI':'GAATTC','BamHI':'GGATCC','HindIII':'AAGCTT','SalI':'GTCGAC',
    'PstI':'CTGCAG','SmaI':'CCCGGG','XbaI':'TCTAGA','KpnI':'GGTACC',
    'ApaI':'GGGCCC','SpeI':'ACTAGT','XhoI':'CTCGAG','NcoI':'CCATGG',
    'EcoRV':'GATATC','BglI':'TGATCA','NsiI':'ATGCAT','SacI':'GAGCTC',
    'PvuII':'CAGCTG','BstYI':'RGATCY','EaeI':'YGGCCR','BseRI':'GAGGAG',
    'NaeI':'GCCGGC','PvuI':'CGATCG','NruI':'TCGCGA'
}
for k,v in sites6.items():
    m=[mm.start()+1 for mm in re.finditer(v, seq)]
    if m:
        print(f"  {k} ({v}): {len(m)} sites, first at {m[:6]}")
        if k=='BseRI': print("   BseRI sites:", m)
